// Fast: no database, no network — pure logic test
@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock private OrderRepository repository;
    @Mock private Clock clock;
    @InjectMocks private OrderService service;

    @Test
    void shouldCalculateDiscountForPremiumUser() {
        // Independent: creates its own test data
        var order = new Order(100L, "Premium", 1000.0);
        when(repository.findById(100L)).thenReturn(Optional.of(order));

        var result = service.calculateFinalPrice(100L);

        // Self-validating: clear pass/fail
        assertThat(result).isEqualTo(900.0); // 10% discount
        verify(repository).findById(100L);
    }

    // Repeatable: fixed time via Clock injection
    @Test
    void shouldRejectExpiredOrders() {
        var fixedTime = Instant.parse("2024-01-15T10:00:00Z");
        when(clock.instant()).thenReturn(fixedTime);
        // Test logic uses injected clock, not LocalDateTime.now()
    }
}

class OrderService {
    private final TaxCalculator taxCalculator;

    public OrderService(TaxCalculator taxCalculator) {
        this.taxCalculator = taxCalculator;
    }

    public OrderSummary processOrder(Order order) {
        var subtotal = calculateSubtotal(order);
        var tax = taxCalculator.calculate(subtotal, order.region());
        var total = subtotal + tax;
        return new OrderSummary(subtotal, tax, total);
    }

    // Previously this was private — hard to test
    // Now extracted to its own class
    private double calculateSubtotal(Order order) {
        return order.items().stream()
            .mapToDouble(item -> item.price() * item.quantity())
            .sum();
    }
}

// Test the public method, which exercises calculateSubtotal indirectly
@Test
void shouldCalculateOrderTotalWithTax() {
    var calculator = mock(TaxCalculator.class);
    var service = new OrderService(calculator);
    var order = new Order(List.of(new Item("Book", 20.0, 2)));

    when(calculator.calculate(40.0, "CA")).thenReturn(4.0);

    var summary = service.processOrder(order);

    assertThat(summary.total()).isEqualTo(44.0);
}

