// Test with fixed time
@Test
void shouldDetectExpiredSubscription() {
    var fixedTime = LocalDateTime.of(2024, 6, 15, 10, 0);
    var clock = Clock.fixed(fixedTime.toInstant(ZoneOffset.UTC), ZoneOffset.UTC);
    var service = new SubscriptionService(clock);
