// Production service with Clock injection
@Service
class SubscriptionService {
    private final SubscriptionRepository repository;
    private final Clock clock;

    public SubscriptionService(SubscriptionRepository repository, Clock clock) {
        this.repository = repository;
        this.clock = clock;
    }

    public boolean isExpired(Long subscriptionId) {
        var sub = repository.findById(subscriptionId)
            .orElseThrow(() -> new NotFoundException("Subscription not found"));
        var now = LocalDateTime.now(clock); // Uses injected clock
        return sub.expiresAt().isBefore(now);
    }
}

// Spring configuration
@Configuration
class ClockConfig {
    @Bean
    public Clock clock() {
        return Clock.systemDefaultZone(); // Real time in production
    }
}

// Test with fixed time
@Test
void shouldDetectExpiredSubscription() {
    var repository = mock(SubscriptionRepository.class);
    var fixedTime = LocalDateTime.of(2024, 6, 15, 14, 30);
    var testClock = Clock.fixed(
        fixedTime.toInstant(ZoneOffset.UTC), 
        ZoneOffset.UTC
    );
    var service = new SubscriptionService(repository, testClock);

    var expiredSub = new Subscription(1L, fixedTime.minusDays(1));
    when(repository.findById(1L)).thenReturn(Optional.of(expiredSub));

    assertThat(service.isExpired(1L)).isTrue();
}
